  top.addView(brand,new LinearLayout.LayoutParams(0,-2,1));
  Button lang=new Button(this);lang.setText(taj?"ТҶ  |  RU":"RU  |  ТҶ");lang.setTextSize(11);lang.setAllCaps(false);lang.setTextColor(GREEN);lang.setBackgroundTintList(android.content.res.ColorStateList.valueOf(SURFACE2));top.addView(lang,new LinearLayout.LayoutParams(D(82),D(42)));
